import React from "react";
import Video from "../Video/Video";
import Anchor from "../Anchor/Anchor";
import { useInView } from 'react-intersection-observer';

function SectionComopnent({ title, video, para, url}) {
  const anime = " transition-all duration-1000 ease-out transform"
  const { ref, inView } = useInView({
      triggerOnce: false, // Trigger the animation only once
      threshold: 0.9, // Trigger when 50% of the element is visible
    });
  return (
    <div className="   md:flex transition-all   m-5">
        <div className=" justify-center items-center md:flex md:flex-col mb-12">
          <h1 className={`text-4xl text-center mb-5 text-yellow-400 ${anime}  ${
          inView ? 'opacity-10 translate-y-0' : 'opacity-100 translate-y-10'
        } }`}>{title}</h1>
          <p className=" p-2 leading-relaxed text-lg">{para}</p>
          <div className=" flex justify-center">

          <Anchor text={"Explore More"} url={url}/>
          </div>
        </div>
        <Video video={video} />
    </div>
  );
}

export default SectionComopnent;
